import app from 'flarum/common/app';

/**
 * The locale to format dates and times in.
 *
 * 🚨 Flarum's locale, NOT the browser's. Every call here used to pass
 * `undefined`, which means "whatever the visitor's browser is set to" — so a
 * German forum read by somebody whose browser is en-US showed
 * "Aug 31 – Sep 6, 2026", "MON"/"TUE" and "1 AM", while every translated string
 * around it was in German. Reported by ClaudiusH.
 *
 * Passing the forum's locale also fixes the 24-hour clock for free: `hour:
 * 'numeric'` is 12-hour in en and 24-hour in de, because that is what those
 * locales mean. There is nothing to configure.
 *
 * Falls back to `undefined` (the old behaviour) if the locale cannot be read,
 * so this can never be worse than it was.
 */
export function loc() {
  try {
    const l = app?.data?.locale || app?.translator?.locale;
    return typeof l === 'string' && l ? l : undefined;
  } catch (e) {
    return undefined;
  }
}

/**
 * The locale to format DATES in: the forum's, unless the admin chose a day or
 * month order. Intl cannot be told an order, but the region decides it — so
 * the forum's language with a GB region reads "31 December 2026" and with a US
 * region "December 31, 2026". Languages that are day-first everywhere simply
 * stay as they are. Times keep loc(): the order setting must not flip the
 * 12/24-hour clock.
 */
export function dateLoc() {
  let order;
  try {
    order = app.forum?.attribute('ernestdefoe-calendar.dateOrder');
  } catch (e) {
    return loc();
  }
  if (order !== 'dmy' && order !== 'mdy') return loc();
  const lang = (loc() || typeof navigator !== 'undefined' && navigator.language || 'en').split('-')[0];
  return lang + (order === 'dmy' ? '-GB' : '-US');
}

/** A 6×7 grid of Dates covering the month, padded to whole weeks. */
export function monthMatrix(year, month, weekStartsOn = 0) {
  const first = new Date(year, month, 1);
  const start = new Date(first);
  const shift = (first.getDay() - weekStartsOn + 7) % 7;
  start.setDate(first.getDate() - shift);
  const days = [];
  for (let i = 0; i < 42; i++) {
    const d = new Date(start);
    d.setDate(start.getDate() + i);
    days.push(d);
  }
  return days;
}
export function sameDay(a, b) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}
export function isToday(d) {
  return sameDay(d, new Date());
}

/** Localised weekday short names, ordered from the configured first day. */
export function weekdayNames(weekStartsOn = 0) {
  // 🚨 This used to be a hardcoded English array, under a docblock that said
  // "localised". Derived from real dates instead: 2023-01-01 was a Sunday, so
  // adding 0..6 days walks Sun→Sat and Intl names them in the forum's locale.
  const base = Array.from({
    length: 7
  }, (_, i) => new Date(2023, 0, 1 + i).toLocaleDateString(loc(), {
    weekday: 'short'
  }));
  return [...base.slice(weekStartsOn), ...base.slice(0, weekStartsOn)];
}
export function monthLabel(year, month) {
  return new Date(year, month, 1).toLocaleDateString(loc(), {
    month: 'long',
    year: 'numeric'
  });
}

// ---- week / day helpers ----

export function startOfDay(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}
export function addDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

/** Midnight of the first day of the week containing `d`. */
export function startOfWeek(d, weekStartsOn = 0) {
  const x = startOfDay(d);
  const shift = (x.getDay() - weekStartsOn + 7) % 7;
  x.setDate(x.getDate() - shift);
  return x;
}

/** The 7 Dates of the week containing `d`, ordered from the configured first day. */
export function weekDays(d, weekStartsOn = 0) {
  const s = startOfWeek(d, weekStartsOn);
  return Array.from({
    length: 7
  }, (_, i) => addDays(s, i));
}

/** "Mon, June 7, 2026" — full label for the day view. */
export function dayTitle(d) {
  return d.toLocaleDateString(dateLoc(), {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric'
  });
}

/** "Jun 1 – 7, 2026" / "Jun 29 – Jul 5, 2026" — label for the week view. */
export function weekRangeLabel(days) {
  const a = days[0];
  const b = days[6];

  // 🚨 Localising the month NAME is not enough — the ORDER is locale-specific
  // too. Hand-building "Aug 31 – Sep 6, 2026" gives a German reader
  // "Aug. 31 – Sep. 6, 2026" when they should see "31. Aug – 6. Sep 2026".
  // formatRange() knows the right order, the right separator and when to elide
  // a repeated month or year, in every locale. It is ES2021 and present in
  // every browser Flarum 2 supports; the hand-built form stays as a fallback
  // for anything exotic rather than throwing.
  return dateRange(a, b, {
    day: 'numeric',
    month: 'short',
    year: 'numeric'
  });
}

/**
 * A date range formatted for the reader's locale, falling back to a plain
 * "a – b" if the engine has no formatRange.
 */
export function dateRange(a, b, opts) {
  try {
    const fmt = new Intl.DateTimeFormat(dateLoc(), opts);
    if (typeof fmt.formatRange === 'function') return fmt.formatRange(a, b);
    return `${fmt.format(a)} – ${fmt.format(b)}`;
  } catch (e) {
    return `${a.toLocaleDateString(dateLoc(), opts)} – ${b.toLocaleDateString(dateLoc(), opts)}`;
  }
}

/** "8 AM", "12 PM" — left-gutter labels for the time grid. */
export function hourLabel(h) {
  return new Date(2000, 0, 1, h).toLocaleTimeString(loc(), {
    hour: 'numeric'
  });
}
/**
 * Lay out the timed (non-all-day) events that touch `day` into a set of
 * positioned segments, splitting overlapping events into side-by-side columns.
 */
export function layoutDay(events, day) {
  const dayStart = startOfDay(day).getTime();
  const dayEnd = dayStart + 86400000;
  const segs = events.filter(e => !e.allDay).map(e => {
    const s = new Date(e.start).getTime();
    const en = e.end ? new Date(e.end).getTime() : s + 3600000; // default 1h
    return {
      e,
      s,
      en
    };
  }).filter(x => x.en > dayStart && x.s < dayEnd).map(x => {
    const s = Math.max(x.s, dayStart);
    const en = Math.min(x.en, dayEnd);
    return {
      ev: x.e,
      startMs: s,
      endMs: Math.max(en, s + 1),
      top: (s - dayStart) / 86400000 * 100,
      height: Math.max((en - s) / 86400000 * 100, 1.6),
      col: 0,
      cols: 1
    };
  }).sort((a, b) => a.startMs - b.startMs || b.endMs - a.endMs);

  // Group into overlap clusters, then assign columns greedily within each.
  let cluster = [];
  let clusterEnd = -Infinity;
  const flush = () => {
    const colEnds = [];
    for (const it of cluster) {
      let placed = false;
      for (let c = 0; c < colEnds.length; c++) {
        if (colEnds[c] <= it.startMs) {
          it.col = c;
          colEnds[c] = it.endMs;
          placed = true;
          break;
        }
      }
      if (!placed) {
        it.col = colEnds.length;
        colEnds.push(it.endMs);
      }
    }
    cluster.forEach(it => it.cols = colEnds.length);
    cluster = [];
    clusterEnd = -Infinity;
  };
  for (const s of segs) {
    if (cluster.length && s.startMs >= clusterEnd) flush();
    cluster.push(s);
    clusterEnd = Math.max(clusterEnd, s.endMs);
  }
  if (cluster.length) flush();
  return segs.map(({
    ev,
    top,
    height,
    col,
    cols
  }) => ({
    ev,
    top,
    height,
    col,
    cols
  }));
}

/**
 * An event's start or end as a Date to read with local getters. An all-day
 * event's dates are stored as those dates at UTC midnight, so they are taken
 * in UTC — read locally they land a day early anywhere west of Greenwich
 * (a 20 September event showed as the 19th on the date tile and the grid).
 */
export function eventDate(ev, iso) {
  const d = new Date(iso);
  return ev.allDay ? new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) : d;
}

/** When an event stops being current: an all-day event runs to the end of its last day. */
export function endsAt(ev) {
  const end = eventDate(ev, ev.end || ev.start);
  return ev.allDay ? end.getTime() + 86400000 : end.getTime();
}

/** Does an event (with absolute start/end) touch the given calendar day? */
export function eventOnDay(ev, day) {
  const s = eventDate(ev, ev.start);
  const e = ev.end ? eventDate(ev, ev.end) : s;
  const dayStart = new Date(day.getFullYear(), day.getMonth(), day.getDate());
  const dayEnd = new Date(dayStart);
  dayEnd.setDate(dayEnd.getDate() + 1);
  return s < dayEnd && e >= dayStart;
}

/** Human-friendly date/time range for an event. */
export function formatRange(ev) {
  const s = eventDate(ev, ev.start);
  const e = ev.end ? eventDate(ev, ev.end) : null;
  const dOpts = {
    weekday: 'short',
    month: 'short',
    day: 'numeric'
  };
  const tOpts = {
    hour: 'numeric',
    minute: '2-digit'
  };
  if (ev.allDay) {
    // Locale-ordered, for the same reason as weekRangeLabel.
    if (e && !sameDay(s, e)) return dateRange(s, e, dOpts);
    return s.toLocaleDateString(dateLoc(), {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
      year: 'numeric'
    });
  }
  const date = s.toLocaleDateString(dateLoc(), dOpts);
  const startT = s.toLocaleTimeString(loc(), tOpts);
  if (!e) return `${date}, ${startT}`;
  if (sameDay(s, e)) return `${date}, ${startT} – ${e.toLocaleTimeString(loc(), tOpts)}`;
  return `${date}, ${startT} – ${e.toLocaleDateString(dateLoc(), dOpts)}, ${e.toLocaleTimeString(loc(), tOpts)}`;
}
export function shortTime(iso) {
  return new Date(iso).toLocaleTimeString(loc(), {
    hour: 'numeric',
    minute: '2-digit'
  });
}

/** Format a Date for a datetime-local input value (local wall time). */
export function toLocalInput(d) {
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
flarum.reg.add('ernestdefoe-calendar', 'common/dates', { loc: loc,dateLoc: dateLoc,monthMatrix: monthMatrix,sameDay: sameDay,isToday: isToday,weekdayNames: weekdayNames,monthLabel: monthLabel,startOfDay: startOfDay,addDays: addDays,startOfWeek: startOfWeek,weekDays: weekDays,dayTitle: dayTitle,weekRangeLabel: weekRangeLabel,dateRange: dateRange,hourLabel: hourLabel,layoutDay: layoutDay,eventDate: eventDate,endsAt: endsAt,eventOnDay: eventOnDay,formatRange: formatRange,shortTime: shortTime,toLocalInput: toLocalInput, });